// FASE 2 horizontal — resuelve que ICP Pack usar. Por defecto casino-escolar (compatibilidad).
// FASE 5 — agrega territory_ids/territory_count opcionales (config de la corrida).
const incoming = $input.first()?.json ?? {};
const icpPackId = incoming.icp_pack_id || null;
const icpPackSlug = incoming.icp_pack_slug || 'atacama-labs';
const filter = icpPackId ? `id=eq.${icpPackId}` : `slug=eq.${icpPackSlug}`;

let territoryIds = incoming.territory_ids;
if (typeof territoryIds === 'string') {
  try { territoryIds = JSON.parse(territoryIds); } catch { territoryIds = null; }
}
if (!Array.isArray(territoryIds) || !territoryIds.length) territoryIds = null;

let territoryCount = Number(incoming.territory_count);
if (!Number.isFinite(territoryCount) || territoryCount <= 0) territoryCount = 5;
territoryCount = Math.min(20, Math.max(1, Math.trunc(territoryCount)));

return [{
  json: {
    territory_ids: territoryIds,
    territory_count: territoryCount,
    icp_pack_url: `https://uwquwjmiofixzugttals.supabase.co/rest/v1/icp_packs?${filter}&select=id,slug,status,discovery&limit=1`,
  },
}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const row = Array.isArray(body) ? body[0] : body;
if (status < 200 || status >= 300 || !row || !row.id) {
  throw new Error(`ICP Pack no encontrado o inaccesible (HTTP ${status || 'unknown'}). Revisa que exista un pack activo con ese id/slug en icp_packs.`);
}
if (row.status !== 'active') {
  throw new Error(`ICP Pack '${row.slug}' esta en estado '${row.status}', no 'active'. No se puede ejecutar un ICP que no esta activo (evita correr configuraciones en preparacion por accidente).`);
}
const templates = row.discovery && row.discovery.open_sources && row.discovery.open_sources[0] && row.discovery.open_sources[0].query_templates;
if (!Array.isArray(templates) || !templates.length) {
  throw new Error(`El ICP Pack '${row.slug}' no tiene query_templates configurados en discovery.open_sources[0].`);
}
const init = $('Init ICP Config').first().json;
return [{
  json: {
    icp_pack_id: row.id,
    icp_pack_slug: row.slug,
    query_templates: templates,
    discovery: row.discovery || {},
    territory_ids: init.territory_ids,
    territory_count: init.territory_count,
  },
}];

const t = $json;
const icp = $('Parse ICP Pack').first().json;
let area;
if (t.city && t.city !== 'Santiago') area = t.city;
else if (t.commune) area = t.commune;
else area = t.city || t.region;

const keywords = icp.query_templates.map(tpl => String(tpl).replace(/\{area\}/g, area));

return {
  json:{
    territory_id:t.id,
    region:t.region,
    commune:t.commune,
    city:t.city,
    priority:Number(t.priority || 3),
    cycle_number:Number(t.cycle_number || 0),
    area,
    icp_pack_id: icp.icp_pack_id,
    keywords,
    job_name:`Atacama Labs - ${area} - ${new Date().toISOString().slice(0,10)}`
  }
};

const original = $json;

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: `http://enbandeja-gmaps:8080/api/v1/jobs/${original.job_id}`,
  timeout: 30000,
  json: true,
});

return {
  json: {
    ...original,
    Status: response.Status,
    status: response.status,
  },
};

const t = $('Prepare Job Context').item.json;
const r = $json;

function norm(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function parseObject(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return {}; }
}

const name = String(r.title || '').trim();
const category = String(r.category || '').trim();
const haystack = `${name} ${category}`.toLowerCase();

// Filtro de tipo de establecimiento: Discovery debe ser amplio,
// pero evitamos resultados obviamente ajenos a colegios/escuelas.
const icpFilter = (($('Parse ICP Pack').first().json.discovery)||{}).result_filter || {};
const positivePattern = icpFilter.positive_pattern || '(coleg|school|escuela|liceo|institut|educacional)';
const negativePattern = icpFilter.negative_pattern || '(conductores|conducci[oó]n|manejo|driving school|danza|baile|karate|taekwondo|f[uú]tbol|football academy|idiomas|language school|universidad|university)';
const positive = new RegExp(positivePattern, 'i').test(haystack);
const negative = new RegExp(negativePattern, 'i').test(haystack);

// Ubicación estructurada entregada por Google Maps.
const ca = parseObject(r.complete_address);
const actualCity = norm(ca.city);
const actualBorough = norm(ca.borough);
const actualState = norm(ca.state);

// El campo address a veces comienza con "Nombre del lugar - ..."
// Lo quitamos para que un colegio llamado "San Fernando" en otra ciudad
// no pase el filtro por contener el término en su propio nombre.
let cleanedAddress = String(r.address || '');
const dashIndex = cleanedAddress.indexOf(' - ');
if (dashIndex >= 0) cleanedAddress = cleanedAddress.slice(dashIndex + 3);
cleanedAddress = norm(cleanedAddress);

const requestedCity = norm(t.city);
const requestedCommune = norm(t.commune);
const requestedArea = norm(t.area);

function containsPlace(field, place) {
  if (!field || !place) return false;
  return field === place || field.includes(place) || place.includes(field);
}

let geoMatch = false;

// Caso RM: cuando city=Santiago y existe comuna, la comuna manda.
// Así "Las Condes" no acepta cualquier resultado de Santiago.
if (requestedCommune && requestedCity === 'santiago') {
  geoMatch =
    containsPlace(actualBorough, requestedCommune) ||
    containsPlace(actualCity, requestedCommune) ||
    cleanedAddress.includes(requestedCommune);
}
// Chicureo/otros sectores con comuna distinta al nombre del área:
// aceptamos área específica o comuna real.
else if (requestedCommune) {
  geoMatch =
    containsPlace(actualCity, requestedArea) ||
    containsPlace(actualBorough, requestedArea) ||
    containsPlace(actualCity, requestedCommune) ||
    containsPlace(actualBorough, requestedCommune) ||
    cleanedAddress.includes(requestedArea) ||
    cleanedAddress.includes(requestedCommune);
}
// Ciudades normales: la ciudad real o borough debe coincidir.
// cleanedAddress queda solo como respaldo.
else {
  geoMatch =
    containsPlace(actualCity, requestedCity) ||
    containsPlace(actualBorough, requestedCity) ||
    cleanedAddress.includes(requestedCity);
}

let domain = null;
if (r.website) {
  try {
    domain = new URL(String(r.website)).hostname.replace(/^www\./,'').toLowerCase();
  } catch {}
}

let placeId = r.place_id ? String(r.place_id) : null;
if (!placeId && r.cid) placeId = `cid:${r.cid}`;
if (!placeId && r.data_id) placeId = `data:${r.data_id}`;

return {
  json: {
    keep: Boolean(name && positive && !negative && placeId && geoMatch),

    territory_id: t.territory_id,
    region: t.region,
    commune: t.commune,
    city: t.city,

    // Datos reales observados en Google Maps para auditoría del filtro.
    actual_city: ca.city || null,
    actual_borough: ca.borough || null,
    actual_state: ca.state || null,
    geo_match: geoMatch,

    name,
    normalized_name: norm(name),
    address: r.address || null,
    website: r.website || null,
    domain,
    phone: r.phone || null,
    google_maps_url: r.link || null,
    google_place_id: placeId,
    source: 'google_maps_selfhosted',
    source_url: r.link || null,
    discovery_status: 'processed',
    icp_pack_id: t.icp_pack_id,
    last_seen_at: new Date().toISOString()
  }
};

const items = $input.all().map(i => i.json).filter(x => x.keep);
const seen = new Set();
const out = [];

for (const x of items) {
  if (seen.has(x.google_place_id)) continue;
  seen.add(x.google_place_id);

  // Campos internos de validación no se guardan en schools.
  const {
    keep,
    actual_city,
    actual_borough,
    actual_state,
    geo_match,
    ...school
  } = x;

  out.push({ json: school });
}

return out;

const icp = $('Parse ICP Pack').first().json;
const areas = (icp.discovery && icp.discovery.areas) || [];
const region = (icp.discovery && icp.discovery.region) || 'Antofagasta';
if (!areas.length) {
  throw new Error(`ICP Pack '${icp.icp_pack_slug}' no tiene discovery.areas configuradas (Region.Antofagasta esperado).`);
}
return areas.map((area, i) => ({
  json: {
    id: null,
    region,
    commune: null,
    city: area,
    priority: i + 1,
    cycle_number: 0,
  },
}));

const rows = $input.all().map(i => i.json);
const failed = rows.filter(r => r.failed);
const ok = rows.filter(r => !r.failed);
const accountsUpserted = ok.reduce((sum, r) => sum + (r.accounts_upserted || 0), 0);
return [{
  json: {
    workflow: 'Atacama Labs - 01 Discovery',
    finished_at: new Date().toISOString(),
    accounts_upserted: accountsUpserted,
    failures: failed.length,
    status: failed.length && !accountsUpserted ? 'failed' : 'completed',
  },
}];
